window.api = {
  getTasks: () => new Promise((resolve) => setTimeout(() => resolve([
    { id: 1, title: "Buy milk" },
    { id: 2, title: "Write tests" }
  ]), 60))
};

function App() {
  const [tasks, setTasks] = React.useState([]);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState(false);

  async function loadTasks() {
    setLoading(true);
    setError(false);

    try {
      const result = await window.api.getTasks();
      setTasks(result);
    } catch {
      setTasks([]);
      setError(true);
    } finally {
      setLoading(false);
    }
  }

  React.useEffect(() => {
    loadTasks();
  }, []);

  return (
    <section>
      <button onClick={loadTasks}>Reload</button>
      {loading && <p data-testid="loading">Loading…</p>}
      {!loading && error && (
        <p role="alert">Could not load tasks</p>
      )}
      {!loading && !error && (
        <ul data-testid="task-list">
          {tasks.map(task => (
            <li key={task.id}>{task.title}</li>
          ))}
        </ul>
      )}
    </section>
  );
}

